window.ICON = function (name, size, cls) {
  const d = window.ICONS[name]; size = size || 20;
  if (!d) return '';
  const attrs = 'class="ic' + (cls ? ' ' + cls : '') + '" width="' + size + '" height="' + size + '" viewBox="0 0 256 256" aria-hidden="true" focusable="false"';
  return d.f ? '<svg ' + attrs + ' fill="currentColor">' + d.p + '</svg>' : '<svg ' + attrs + ' fill="none" stroke="currentColor" stroke-width="16" stroke-linecap="round" stroke-linejoin="round">' + d.p + '</svg>';
};
